declare cid uuid;
begin
  select id into cid from public.courses where slug = 'bib-101';
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 Wisdom for Daily Life: Proverbs$j$, $j${"readings": [{"title": "Proverbs 1 (King James Version)", "url": "/portal/bible/Proverbs/1"}, {"title": "Proverbs 3 (King James Version)", "url": "/portal/bible/Proverbs/3"}, {"title": "Proverbs 15 (King James Version)", "url": "/portal/bible/Proverbs/15"}, {"title": "Proverbs 22 (King James Version)", "url": "/portal/bible/Proverbs/22"}], "body": "Read Proverbs 1, 3, 15 and 22 in the King James Version. Then read this lesson.\n\nProverbs is a collection of short, wise sayings, mostly written by Solomon. A proverb states a general truth that is usually right, not a promise that is always right. The book is written as a father speaking to his son. It gives practical guidance on speech, friends, work, money, anger, discipline and the choices that shape a life. The theme is stated in Proverbs 1:7: the fear of the LORD is the beginning of knowledge. Wisdom is not just knowing facts. It is knowing how to live well before God.\n\nKey words: wisdom, fear of the LORD, folly, discipline, speech.\n\nYour task: (1) Write Proverbs 1:7 in your own words. (2) Pick one proverb from chapters 3, 15 or 22 and say how it could help a student. (3) Tell the difference between a wise person and a fool in Proverbs.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Proverbs is the book of wisdom. Most of it was written by King Solomon, the man who asked God for an understanding heart. The book is written like a father talking to his son, and it covers everyday life: how to speak, how to choose friends, how to work, how to handle money and how to control anger.\n\nThe theme of the whole book is found in Proverbs 1:7. The fear of the LORD is the beginning of knowledge: but fools despise wisdom and instruction. The fear of the LORD means respect, reverence and obedience. Real wisdom starts with God. A person can learn many facts and still be foolish if they leave God out.\n\nA proverb is a short saying that states a general truth. It is usually right, but it is not a promise in every case. For example, Proverbs 22:6 says, Train up a child in the way he should go: and when he is old, he will not depart from it. It teaches that early training matters and has a lasting effect. It does not promise that every child will turn out the same.\n\nProverbs pays special attention to words. Proverbs 15:1 says, A soft answer turneth away wrath: but grievous words stir up anger. How you answer can calm a fight or start one. Students deal with this every day, in the hallway, in a group chat and at home.\n\nProverbs also teaches trust. Proverbs 3:5 and 6 say, Trust in the LORD with all thine heart; and lean not unto thine own understanding. In all thy ways acknowledge him, and he shall direct thy paths. When you face a decision about school, friends or your future, start there. Bring God into every part of the decision.\n\nThroughout the book the wise person and the fool are put side by side. The wise person listens, learns and plans. The fool is quick to speak, slow to listen and unwilling to be corrected. Proverbs invites us to choose wisdom while we are young.\n\nYour task is to put Proverbs 1:7 in your own words, choose one proverb and tell how it helps a student, and tell the difference between a wise person and a fool. Then take the four question check.\n\nWisdom begins with God and shows up in the small choices of every day. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 Wisdom for Daily Life: Proverbs$j$);
end
$seed$;
